BEGIN;
CREATE OR REPLACE FUNCTION collateral_resilience_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'collateral resilience history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS collateral_resilience_scopes (scope_hash text PRIMARY KEY CHECK(scope_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS collateral_resilience_feature12_bindings (scope_hash text NOT NULL REFERENCES collateral_resilience_scopes(scope_hash), binding_hash text NOT NULL CHECK(binding_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,binding_hash));
CREATE TABLE IF NOT EXISTS collateral_resilience_balances (scope_hash text NOT NULL REFERENCES collateral_resilience_scopes(scope_hash), observation_hash text NOT NULL CHECK(observation_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,observation_hash));
CREATE TABLE IF NOT EXISTS collateral_resilience_positions (scope_hash text NOT NULL REFERENCES collateral_resilience_scopes(scope_hash), observation_hash text NOT NULL CHECK(observation_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,observation_hash));
CREATE TABLE IF NOT EXISTS collateral_resilience_funding_borrow (scope_hash text NOT NULL REFERENCES collateral_resilience_scopes(scope_hash), observation_hash text NOT NULL CHECK(observation_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,observation_hash));
CREATE TABLE IF NOT EXISTS collateral_resilience_dependencies (scope_hash text NOT NULL REFERENCES collateral_resilience_scopes(scope_hash), observation_hash text NOT NULL CHECK(observation_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,observation_hash));
CREATE TABLE IF NOT EXISTS collateral_resilience_liquidity (scope_hash text NOT NULL REFERENCES collateral_resilience_scopes(scope_hash), observation_hash text NOT NULL CHECK(observation_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,observation_hash));
CREATE TABLE IF NOT EXISTS collateral_resilience_envelopes (scope_hash text NOT NULL REFERENCES collateral_resilience_scopes(scope_hash), envelope_hash text NOT NULL CHECK(envelope_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,envelope_hash));
CREATE TABLE IF NOT EXISTS collateral_resilience_request_claims (scope_hash text NOT NULL REFERENCES collateral_resilience_scopes(scope_hash), idempotency_key text NOT NULL, request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'), envelope_hash text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,idempotency_key), FOREIGN KEY(scope_hash,envelope_hash) REFERENCES collateral_resilience_envelopes(scope_hash,envelope_hash));
CREATE TABLE IF NOT EXISTS collateral_resilience_conflicts (scope_hash text NOT NULL REFERENCES collateral_resilience_scopes(scope_hash), conflict_hash text NOT NULL CHECK(conflict_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,conflict_hash));
CREATE TABLE IF NOT EXISTS collateral_resilience_test_center_bundles (run_id text PRIMARY KEY REFERENCES agent_test_center_runs(run_id), scope_hash text NOT NULL, envelope_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(scope_hash,envelope_hash) REFERENCES collateral_resilience_envelopes(scope_hash,envelope_hash));
DO $$ DECLARE item text; BEGIN FOREACH item IN ARRAY ARRAY['collateral_resilience_scopes','collateral_resilience_feature12_bindings','collateral_resilience_balances','collateral_resilience_positions','collateral_resilience_funding_borrow','collateral_resilience_dependencies','collateral_resilience_liquidity','collateral_resilience_envelopes','collateral_resilience_request_claims','collateral_resilience_conflicts','collateral_resilience_test_center_bundles'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_immutable ON %I', item,item); EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION collateral_resilience_reject_mutation()', item,item); END LOOP; END $$;
COMMIT;
